Code.Terraform:
```hcl
resource "aws_bedrockagentcore_browser" "example_resource" {
  name = "example_resource"

  network_configuration {
    network_mode = "VPC"
  }

  # Critical: recording defaults to disabled, leaving no record of the session
  recording {
    enabled = true
    s3_location {
      bucket = aws_s3_bucket.example_resource.bucket
      prefix = "browser-recordings/"
    }
  }
}
```
